INSERT INTO `components` VALUES (11,2,18,'Engine controller','(демо) Контроллер системы управления двигателем','','<p data-v-8345040e=\"\" class=\"project-item__text\">Центральное устройство системы управления двигателем внутреннего сгорания. На основании информации от датчиков осуществляет управление исполнительными механизмами для оптимальной работы двигателя при заданном уровне токсичности отработавших газов.</p>\r\n<p data-v-8345040e=\"\" class=\"project-item__text\">Выполняет функции диагностики элементов, входящих в электронную систему управления двигателем, и контроля деградации его компонентов, влияющих на токсичности ОГ.</p>\r\n<p data-v-8345040e=\"\" class=\"project-item__text\">Обеспечивает высокий уровень потребительских качеств автомобиля.</p>','<p>Центральное устройство системы управления ДВС. Осуществляет управление исполнительными механизмами, выполняет функции диагностики и контроля деградации компонентов.</p>',NULL,NULL,'[{\"title_en\": null, \"title_ru\": \"Управление исполнительными механизмами ДВС\"}, {\"title_en\": null, \"title_ru\": \"Диагностика элементов электронной системы управления двигателем\"}, {\"title_en\": null, \"title_ru\": \"Контроль деградации элементов электронной системы управления двигателем\"}, {\"title_en\": null, \"title_ru\": \"Контроль деградации элементов электронной системы управления двигателем\"}]','[{\"title_en\": null, \"title_ru\": \"LADA GRANTA\"}, {\"title_en\": null, \"title_ru\": \"LADA GRANTA FH.2\"}, {\"title_en\": null, \"title_ru\": \"LADA LARGUS FH.2\"}, {\"title_en\": null, \"title_ru\": \"LADA X-RAY\"}]','[{\"title_en\": null, \"title_ru\": \"Нормы токсичности\", \"value_en\": null, \"value_ru\": \"Евро 5, Евро 5+, Евро 6\"}, {\"title_en\": null, \"title_ru\": \"Количество цилиндров\", \"value_en\": null, \"value_ru\": \"до 4-х\"}, {\"title_en\": null, \"title_ru\": \"Тип топлива и конфигурация ДВС\", \"value_en\": null, \"value_ru\": \"Бензин, распределенный впрыск во впускной коллектор\"}, {\"title_en\": null, \"title_ru\": \"Номинальное напряжение бортовой сети\", \"value_en\": null, \"value_ru\": \"12В\"}, {\"title_en\": null, \"title_ru\": \"Коммуникация\", \"value_en\": null, \"value_ru\": \"2 канала CAN и 1 канал LIN\"}, {\"title_en\": null, \"title_ru\": \"Диагностика\", \"value_en\": null, \"value_ru\": \"UDS on CAN (ISO 15765)\"}, {\"title_en\": null, \"title_ru\": \"Дополнительные функции\", \"value_en\": null, \"value_ru\": \"DVVT, S&S, Turbo; ETAS INCA CCP\"}, {\"title_en\": null, \"title_ru\": \"Габаритные размеры (ДxШxВ)\", \"value_en\": null, \"value_ru\": \"208x104x46 мм\"}, {\"title_en\": null, \"title_ru\": \"Вес\", \"value_en\": null, \"value_ru\": \"0,4 кг\"}, {\"title_en\": null, \"title_ru\": \"Материал корпуса\", \"value_en\": null, \"value_ru\": \"алюминиевый сплав (штампованная крышка и литое основание)\"}, {\"title_en\": null, \"title_ru\": \"Разъем\", \"value_en\": null, \"value_ru\": \"Molex 560045-0821 (82 контакта), Molex 560045-1201 (120 контактов)\"}, {\"title_en\": null, \"title_ru\": \"Место установки\", \"value_en\": null, \"value_ru\": \"моторный отсек\"}, {\"title_en\": null, \"title_ru\": \"Степень защиты оболочки\", \"value_en\": null, \"value_ru\": \"IP67 ГОСТ 14254-96\"}, {\"title_en\": null, \"title_ru\": \"Рабочая температура по ГОCТ 15150\", \"value_en\": null, \"value_ru\": \"-40°C ..... +105°C\"}]',1,'2021-07-08 05:39:35','2023-09-15 05:46:03',NULL),(13,2,9,'Блок управления противоугонной системой','Блок управления противоугонной системой','','<p align=\"justify\">Блок управления противоугонной системой (БУПС) предназначен для обеспечения\r\nдополнительной защиты от неразрешенного использования, путем подачи\r\nкодовой команды, запрещающей контроллеру управления двигателем\r\nзапуск двигателя.</p><p class=\"align-justify\">Противоугонная система выполняет ряд дополнительных\r\nфункций, таких, как управление задними противотуманными огнями и реле питания электростеклоподъемников, подача предупреждающего звукового сигнала, подача предупреждающего звукового сигнала при включении передачи заднего хода, осуществление задержки и плавного погасания плафона освещения салона.</p>','<p align=\"justify\">Блок управления противоугонной системой (БУПС) предназначен для обеспечения\r\nдополнительной защиты от неразрешенного использования, путем подачи\r\nкодовой команды,&nbsp;<!--StartFragment-->запрещающей запуск двигателя.<!--EndFragment--></p>',NULL,NULL,'[{\"title_en\": null, \"title_ru\": \"Запрет запуска двигателя при неразрешенном использовании\"}, {\"title_en\": null, \"title_ru\": \"Осуществление задержки и плавного погасания плафона освещения салона\"}, {\"title_en\": null, \"title_ru\": \"Подача предупреждающего звукового сигнала\"}, {\"title_en\": null, \"title_ru\": \"Подача предупреждающего звукового сигнала при включении передачи заднего хода\"}, {\"title_en\": null, \"title_ru\": \"Прием радиосигнала от ключа зажигания\"}, {\"title_en\": null, \"title_ru\": \"Управление задними противотуманными огнями\"}, {\"title_en\": null, \"title_ru\": \"Управление реле питания электростеклоподъемников\"}]','[{\"title_en\": null, \"title_ru\": \"Granta FL\"}]','[{\"title_en\": null, \"title_ru\": \"Номинальное напряжение бортовой сети\", \"value_en\": null, \"value_ru\": \"14В\"}, {\"title_en\": null, \"title_ru\": \"Коммуникация\", \"value_en\": null, \"value_ru\": \"K-LINE\"}, {\"title_en\": null, \"title_ru\": \"Габаритные размеры (ДxШxВ)\", \"value_en\": null, \"value_ru\": \"126x60,5x32 мм\"}, {\"title_en\": null, \"title_ru\": \"Вес\", \"value_en\": null, \"value_ru\": \"0,07 кг\"}, {\"title_en\": null, \"title_ru\": \"Материал корпуса\", \"value_en\": null, \"value_ru\": \"ABS (пластиковая лицевая панель и корпус)\"}, {\"title_en\": null, \"title_ru\": \"Разъем\", \"value_en\": null, \"value_ru\": \"AMP 174055-2\"}, {\"title_en\": null, \"title_ru\": \"Место установки\", \"value_en\": null, \"value_ru\": \"салон автомобиля\"}, {\"title_en\": null, \"title_ru\": \"Степень защиты оболочки\", \"value_en\": null, \"value_ru\": \"IP4X ГОСТ 14254\"}, {\"title_en\": null, \"title_ru\": \"Рабочая температура по ГОCТ 15150\", \"value_en\": null, \"value_ru\": \"-40°C ..... +85°C\"}]',1,'2021-07-21 11:42:12','2023-09-15 05:46:03',NULL),(14,2,1,'ECSC M74.9','КСУД М74.9','(Легк. тр-т)','<p align=\"justify\">КСУД является центральным устройством системы управления двигателем внутреннего сгорания. </p> <p align=\"justify\">На основании информации от датчиков, осуществляет управление исполнительными механизмами, обеспечивающих оптимальную работу двигателя при заданном уровне токсичности отработавших газов.</p> <p align=\"justify\">Выполняет функции диагностики элементов, входящих в электронную систему управления двигателем, и контроля деградации его компонентов, влияющих на токсичности ОГ.</p> <p align=\"justify\">Обеспечивает высокий уровень потребительских качеств автомобиля.</p>','<p align=\"justify\">КСУД является центральным устройством системы управления двигателем внутреннего сгорания. </p>','<p><!--StartFragment-->Engine Control System Controller (ECSC) is a central device in the internal combustion engine control system.<!--EndFragment--></p>','<p><!--StartFragment-->Engine Control System Controller (ECSC) is a central device in the internal combustion engine control system.</p><p> Based on information from the sensors, controls actuators providing for optimal engine operation with the set level of spent gases toxicity.</p><p> Performs functions of diagnostics of the elements within the electronic engine control system and monitoring of degradation in its components influencing spent gases toxicity.</p><p> Provides for high level of the vehicle consumer properties.<!--EndFragment--></p>','[{\"title_en\": \"The controller is supplied from the vehicle network with nominal voltage of 13.5 V.\", \"title_ru\": \"Питание контроллера осуществляется от бортовой сети автомобиля с номинальным напряжением 13,5 В\"}, {\"title_en\": \"The controller is designed for installation on a vehicle, designed for operation under conditions of moderate and tropical climate at ambient air temperatures from minus 40 °С to plus 45 °С and moisture 90% at temperature 27 °С.\", \"title_ru\": \"Контроллер  предназначен для установки на автомобиль, рассчитанный на эксплуатацию в условиях умеренного и тропического климата при температурах окружающего воздуха от минус 40 °С до плюс 45 °С и влажности 90% при температуре 27 °С.\", \"title_description\": null}, {\"title_en\": \"The controller is designed for installation in the engine compartment of the vehicle or in its interior.\", \"title_ru\": \"Контроллер предназначен для установки в моторном отсеке автомобиля или в его салоне.\", \"title_description\": null}]','[{\"title_en\": \"Vesta\", \"title_ru\": \"Vesta\"}, {\"title_en\": \"Largus\", \"title_ru\": \"Largus\"}, {\"title_en\": \"Granta\", \"title_ru\": \"Granta\"}, {\"title_en\": \"Niva Legend\", \"title_ru\": \"Niva Legend\"}, {\"title_en\": \"Niva Trevel\", \"title_ru\": \"Niva Trevel\"}, {\"title_en\": \"XJO\", \"title_ru\": \"XJO\"}, {\"title_en\": \"HGH\", \"title_ru\": \"HGH\"}, {\"title_en\": \"Gazelle Business\", \"title_ru\": \"Газель Бизнес\"}, {\"title_en\": \"Gazelle Next\", \"title_ru\": \"Газель Next\"}, {\"title_en\": \"Gazelle NN\", \"title_ru\": \"Газель NN\"}]','[{\"title_en\": \"Toxicity standards\", \"title_ru\": \"Нормы токсичности\", \"value_en\": \"Euro 4, Euro 5, Euro 6\", \"value_ru\": \"Евро 4, Евро 5, Евро 6\"}, {\"title_en\": \"Number of cylinders\", \"title_ru\": \"Количество цилиндров\", \"value_en\": \"Up to 4\", \"value_ru\": \"до 4-х\"}, {\"title_en\": \"Fuel type and ICE configuration\", \"title_ru\": \"Тип топлива и конфигурация ДВС\", \"value_en\": \"Gasoline, gasoline-gas (when MR is connected), distributed injection into the intake manifold\", \"value_ru\": \"Бензин, бензин-газ (при подключении MR), распределённый впрыск во впускной коллектор\"}, {\"title_en\": \"The rated voltage of the onboard network\", \"title_ru\": \"Номинальное напряжение бортовой сети\", \"value_en\": \"12V\", \"value_ru\": \"12В\"}, {\"title_en\": \"Communication\", \"title_ru\": \"Коммуникация\", \"value_en\": \"2 CAN channels\", \"value_ru\": \"2 канала CAN\"}, {\"title_en\": \"Diagnostics\", \"title_ru\": \"Диагностика\", \"value_en\": \"UDS on CAN (ISO 15765)\", \"value_ru\": \"UDS on CAN (ISO 15765)\"}, {\"title_en\": \"Additional functions\", \"title_ru\": \"Дополнительные функции\", \"value_en\": \"VVT, intake system valve\", \"value_ru\": \"VVT, клапан системы впуска\"}, {\"title_en\": \"Overall dimensions (LxWxH)\", \"title_ru\": \"Габаритные размеры (ДxШxВ)\", \"value_en\": \"208x127.2x37.5 mm\", \"value_ru\": \"208x127,2x37,5 мм\"}, {\"title_en\": \"Weight\", \"title_ru\": \"Вес\", \"value_en\": \"0.45 kg\", \"value_ru\": \"0,45 кг\"}, {\"title_en\": \"Body material\", \"title_ru\": \"Материал корпуса\", \"value_en\": \"Aluminum alloy (cast cover and base)\", \"value_ru\": \"Аллюминиевый сплав (литые крышка и основание)\"}, {\"title_en\": \"Connector\", \"title_ru\": \"Разъем\", \"value_en\": \"Molex 502225-0801 or JSC \\\"Zavod Atlant\\\" (80 pins)\", \"value_ru\": \"Molex 502225-0801 или АО \\\"Завод Атлант\\\" (80 контактов)\"}, {\"title_en\": \"Place of installation\", \"title_ru\": \"Место установки\", \"value_en\": \"Engine compartment\", \"value_ru\": \"Моторный отсек\"}, {\"title_en\": \"IP degree of protection\", \"title_ru\": \"Степень защиты оболочки\", \"value_en\": \"IP54 GOST 14254\", \"value_ru\": \"IP67 ГОСТ 14254\"}, {\"title_en\": \"Operating temperature according to GOST 15150\", \"title_ru\": \"Рабочая температура по ГОCТ 15150\", \"value_en\": \"-40°C ..... +85°C\", \"value_ru\": \"-40°C ..... +85°C\"}]',1,'2021-08-03 04:58:27','2024-01-09 11:22:36',NULL),(16,2,10,'Модуль впуска','Модуль впуска','','<p align=\"justify\">Модуль впуска является одним из ключевых компонентов современного ДВС и предназначен для подачи и распределения воздуха между цилиндрами двигателя.</p> <p align=\"justify\">Оптимальная настройка длин, диаметра каналов и объема ресивера обеспечивает высокие эффективные показатели ДВС.</p> <p align=\"justify\">Применение пластика в качестве материала корпуса повышает эффективные показатели за счет существенного снижения эффекта подогрева заряда на впуске, при снижении веса двигателя.</p>','<p align=\"justify\">Модуль впуска является одним из ключевых компонентов современного ДВС и предназначен для подачи и распределения воздуха между цилиндрами двигателя.</p>',NULL,NULL,'[{\"title_en\": \"Подача между цилиндрами двигателя,\", \"title_ru\": \"Конструкция оптимизирована для работы в составе с ДВС ВАЗ-21127 и ВАЗ-21129 на автомобилях Datsun, Lada Granta, Vesta, X-Ray и Largus\"}, {\"title_en\": \"Распределение воздуха между цилиндрами двигателя\", \"title_ru\": \"Распределение воздуха между цилиндрами двигателя\"}, {\"title_en\": null, \"title_ru\": \"Подача воздуха между цилиндрами двигателя\"}, {\"title_en\": null, \"title_ru\": \"Система ступенчатой регулировки волновой настройки впускной системы с применением дополнительной резонансной камеры\"}, {\"title_en\": null, \"title_ru\": \"Сокращение количества корпусных деталей за счет применения специальной оснастки при изготовлении, по сравнению с аналогичными изделиями на рынке\"}]','[{\"title_ru\": \"Vesta/Vesta Ph.2\"}, {\"title_en\": null, \"title_ru\": \"X-Ray\"}, {\"title_en\": null, \"title_ru\": \"Largus\"}, {\"title_en\": null, \"title_ru\": \"Granta FL\"}]','[{\"title_en\": null, \"title_ru\": \"Габаритные размеры (ДxШxВ)\", \"value_en\": null, \"value_ru\": \"463,2x481,7x266,5 мм\"}, {\"title_en\": null, \"title_ru\": \"Вес\", \"value_en\": null, \"value_ru\": \"3,76 кг\"}, {\"title_en\": null, \"title_ru\": \"Материал корпуса\", \"value_en\": null, \"value_ru\": \"полиамид стеклонаполненный (PA6-GF30)\"}, {\"title_en\": null, \"title_ru\": \"Место установки\", \"value_en\": null, \"value_ru\": \"моторный отсек\"}, {\"title_en\": null, \"title_ru\": \"Рабочая температура по ГОCТ 15150\", \"value_en\": null, \"value_ru\": \"-40°C ..... +125°C\"}]',1,'2021-08-03 04:58:27','2023-09-15 05:46:03',NULL),(17,2,11,'Топливная рампа','Топливная рампа','(неакт.)','<p align=\"justify\">Топливная рампа обеспечивает подвод и распределение бензина между форсунками.</p> <p align=\"justify\">Разработана для применения на ДВС с распределенным впрыском во впускной трубопровод и бессливной системой топливоподачи.</p>','<p align=\"justify\">Топливная рампа обеспечивает подвод и распределение бензина между форсунками.</p>',NULL,NULL,'[{\"title_en\": null, \"title_ru\": \"Квадратный профиль сечения и увеличенный объем, по сравнению с аналогами, обеспечивает улучшенные характеристики по демпфированию пульсаций давления в топливной системе, снижая межцилиндровую неравномерность топливоподачи\"}, {\"title_en\": null, \"title_ru\": \"Наличие диагностического штуцера облегчает диагностику топливной системы при производстве и эксплуатации автомобиля\"}, {\"title_en\": null, \"title_ru\": \"Разработана для применения на 16 кл. ДВС ВАЗ-21127, ВАЗ-21129, ВАЗ-21179\"}, {\"title_en\": null, \"title_ru\": \"Применение бессливной конструкции снижает количество соединений и трубок, что приводит к снижению топливных испарений автомобиля\"}]','[{\"title_ru\": \"Granta\"}, {\"title_en\": null, \"title_ru\": \"Vesta\"}, {\"title_en\": null, \"title_ru\": \"Largus\"}]','[{\"title_en\": null, \"title_ru\": \"Рабочее давление бензина\", \"value_en\": null, \"value_ru\": \"380±6 кПа\"}, {\"title_en\": null, \"title_ru\": \"Максимальное давление бензина\", \"value_en\": null, \"value_ru\": \"650 кПа\"}, {\"title_en\": null, \"title_ru\": \"Подключение\", \"value_en\": null, \"value_ru\": \"штуцер подвода топлива под быстроразъемное соединение (соответствует стандарту SAE J2044: 2009)\"}, {\"title_en\": null, \"title_ru\": \"Габаритные размеры (ДxШxВ)\", \"value_en\": null, \"value_ru\": \"376x34,5x74,6 мм\"}, {\"title_en\": null, \"title_ru\": \"Вес\", \"value_en\": null, \"value_ru\": \"0,23 кг\"}, {\"title_en\": null, \"title_ru\": \"Материал корпуса\", \"value_en\": null, \"value_ru\": \"сталь нержавеющая\"}, {\"title_en\": null, \"title_ru\": \"Место установки\", \"value_en\": null, \"value_ru\": \"моторный отсек\"}, {\"title_en\": null, \"title_ru\": \"Рабочая температура по ГОCТ 15150\", \"value_en\": null, \"value_ru\": \"-40°C ..... +125°C\"}]',0,'2021-08-03 04:58:27','2023-09-15 05:46:03',NULL),(22,4,72,'Центральный блок кузовной электроники','Центральный блок кузовной электроники','(неакт.)','<p align=\"justify\">Центральный блок кузовной электроники (ЦБКЭ) предназначен для выполнения функций управления тревожной сигнализацией, стеклоочистителем ветрового стекла, обогревами ветрового и заднего стекол, обогревами боковых зеркал и сидений, головным светом и указателями поворота, плафоном освещения салона, энергосбережением устройств внутреннего освещения автомобиля, центральным замком, замком багажника от кнопки в салоне, электроприводом стеклоподъемников и боковых зеркал.</p>','<p align=\"justify\">Центральный блок кузовной электроники (ЦБКЭ) предназначен для выполнения функций управления тревожной сигнализацией, стеклоочистителем ветрового стекла, обогревами ветрового и заднего стекол, обогревами боковых зеркал и сидений.</p>',NULL,NULL,'[{\"title_en\": \"Управление \\n\\nтревожной сигнализацией\", \"title_ru\": \"Управление головным светом и указателями поворота\"}, {\"title_en\": \"Управление\\nстеклоочистителем ветрового стекла\", \"title_ru\": \"Управление замком багажника от кнопки в салоне\"}, {\"title_en\": \"Управление \\nобогревами ветрового и заднего стекол\", \"title_ru\": \"Управление обогревами боковых зеркал и сидений\"}, {\"title_en\": \"Управление \\nобогревами боковых зеркал и сидений\", \"title_ru\": \"Управление обогревами ветрового и заднего стекол\"}, {\"title_en\": \"Управление \\nголовным светом и указателями поворота\", \"title_ru\": \"Управление плафоном освещения салона\"}, {\"title_en\": \"Управление \\nплафоном освещения салона\", \"title_ru\": \"Управление стеклоочистителем ветрового стекла\"}, {\"title_en\": \"Управление \\nэнергосбережением устройств внутреннего освещения автомобиля\", \"title_ru\": \"Управление тревожной сигнализацией\"}, {\"title_en\": \"Управление \\nцентральным замком\", \"title_ru\": \"Управление центральным замком\"}, {\"title_en\": \"Управление \\nзамком багажника от кнопки в салоне\", \"title_ru\": \"Управление электроприводом стеклоподъемников и боковых зеркал\"}, {\"title_en\": \"Управление \\nэлектроприводом стеклоподъемников и боковых зеркал\", \"title_ru\": \"Управление энергосбережением устройств внутреннего освещения автомобиля\"}]','[{\"title_ru\": \"Granta\"}, {\"title_en\": null, \"title_ru\": \"Largus\"}]','[{\"title_en\": null, \"title_ru\": \"Номинальное напряжение питания\", \"value_en\": null, \"value_ru\": \"13,5 В\"}, {\"title_en\": null, \"title_ru\": \"Коммуникация\", \"value_en\": null, \"value_ru\": \"1 канал CAN, 2 канала LIN\"}, {\"title_en\": null, \"title_ru\": \"Диагностика\", \"value_en\": null, \"value_ru\": \"UDS on CAN (ISO 15765)\"}, {\"title_en\": null, \"title_ru\": \"Габаритные размеры (ДxШxВ)\", \"value_en\": null, \"value_ru\": \"150x126,4x30,1 мм\"}, {\"title_en\": null, \"title_ru\": \"Вес\", \"value_en\": null, \"value_ru\": \"0,2 кг\"}, {\"title_en\": null, \"title_ru\": \"Материал корпуса\", \"value_en\": null, \"value_ru\": \"ABS\"}, {\"title_en\": null, \"title_ru\": \"Разъемы\", \"value_en\": null, \"value_ru\": \"XP1 - TE 2-1379604-1; XP2 - TE 2-1379604-2; XP3 - галета ИЮТЛ.434427.001; XP4 - галета ИЮТЛ.434427.001\"}, {\"title_en\": null, \"title_ru\": \"Место установки\", \"value_en\": null, \"value_ru\": \"салон автомобиля\"}, {\"title_en\": null, \"title_ru\": \"Степень защиты оболочки\", \"value_en\": null, \"value_ru\": \"IP5K0 по ISO 20653\"}, {\"title_en\": null, \"title_ru\": \"Рабочая температура по ГОCТ 15150\", \"value_en\": null, \"value_ru\": \"-40°C ..... +85°C\"}]',0,'2021-08-03 04:58:27','2024-06-24 09:39:04',NULL),(23,4,63,'Блок кузовной электроники LEMM','Блок кузовной электроники LEMM','(неакт.)','<p align=\"justify\">Блок LEMM предназначен для выполнения функций управления обогревом передних и задних сидений и ветрового стекла, складыванием/раскладыванием наружных зеркал заднего вида, системой внешнего освещения, стеклоочистителем ветрового стекла и регулированием угла наклона фар.</p>','<p align=\"justify\">Блок LEMM предназначен для выполнения функций управления обогревом передних и задних сидений и ветрового стекла, складыванием/раскладыванием наружных зеркал заднего вида,&nbsp;<!--StartFragment-->системой внешнего освещения.<!--EndFragment--></p>',NULL,NULL,'[{\"title_en\": \"Управление \\n\\nобогревом передних и задних сидений\", \"title_ru\": \"Управление обогревом ветрового стекла\"}, {\"title_en\": \"Управление\\nобогревом ветрового стекла\", \"title_ru\": \"Управление обогревом передних и задних сидений\"}, {\"title_en\": \"Управление \\nскладыванием/раскладыванием наружных зеркал заднего вида\", \"title_ru\": \"Управление регулированием угла наклона фар\"}, {\"title_en\": \"Управление \\nсистемой внешнего освещения\", \"title_ru\": \"Управление системой внешнего освещения\"}, {\"title_en\": \"Управление \\nстеклоочистителем ветрового стекла\", \"title_ru\": \"Управление складыванием/раскладыванием наружных зеркал заднего вида\"}, {\"title_en\": \"Управление \\nрегулированием угла наклона фар\", \"title_ru\": \"Управление стеклоочистителем ветрового стекла\"}, {\"title_en\": null, \"title_ru\": \"Разработан специально под требования АВТОВАЗ для Lada Vesta Ph.2\"}]','[{\"title_ru\": \"Vesta Ph.2 (2022 год)\"}]','[{\"title_en\": null, \"title_ru\": \"Коммуникация\", \"value_en\": null, \"value_ru\": \"1 канал CAN, 2 канала LIN\"}, {\"title_en\": null, \"title_ru\": \"Диагностика\", \"value_en\": null, \"value_ru\": \"UDS on CAN (ISO 15765)\"}, {\"title_en\": null, \"title_ru\": \"Номинальное нап