rheated, diagnostics of headlight LEDs break and short circuit\", \"title_ru\": \"Обеспечение требуемого тока ГО, ДХО, ДС и БС при различном напряжении питания, снижение выдаваемого тока на светодиоды фары при перегреве фары, диагностика обрыв и КЗ светодиодов фары\"}]','[{\"title_en\": \"VESTA August 2023\", \"title_ru\": \"Веста август 2023г\"}]','[{\"title_en\": \"Current of daytime running lights (DRL) LEDs\", \"title_ru\": \"Ток светодиодов дневных ходовых огней (ДХО)\", \"value_en\": \"0.7A\", \"value_ru\": \"0,7 А\"}, {\"title_en\": \"Current of marker lights (ML) LEDs\", \"title_ru\": \"Ток светодиодов габаритных огней (ГО)\", \"value_en\": \"0.35A\", \"value_ru\": \"0,35 А\"}, {\"title_en\": \"Current of dipped beam (DB) LEDs\", \"title_ru\": \"Ток светодиодовближнего света ( БС)\", \"value_en\": \"1.14A\", \"value_ru\": \"1,14 А\"}, {\"title_en\": \"Current of main beam (MB) LEDs\", \"title_ru\": \"Ток светодиодов дальнего света (ДС)\", \"value_en\": \"1.08 A\", \"value_ru\": \"1,08 А\"}, {\"title_en\": \"Overall dimensions\", \"title_ru\": \"Габаритные размеры (ДxШxВ)\", \"value_en\": \"107x107x37 mm\", \"value_ru\": \"107х107х37 мм\"}, {\"title_en\": \"Body material\", \"title_ru\": \"Материал корпуса\", \"value_en\": \"armamide\", \"value_ru\": \"армамид\"}, {\"title_en\": \"Connector\", \"title_ru\": \"Разъем\", \"value_en\": \"1452842-3 (TE) or equivalent\", \"value_ru\": \"1452842-3 (TE) или аналогичный\"}, {\"title_en\": \"Product operating mode\", \"title_ru\": \"Режим работы изделия\", \"value_en\": \"S1 (continuous rated)\", \"value_ru\": \"S1 (продолжительный номинальный)\"}, {\"title_en\": \"Degree of protection\", \"title_ru\": \"Степень защиты\", \"value_en\": \"IP67 for LDM mounted on the headlamp\", \"value_ru\": \"IP67 для LDM установленного на фару\"}, {\"title_en\": \"Operating temperature according to GOST 15150\", \"title_ru\": \"Рабочая температура ГОCТ 15150\", \"value_en\": \"-40°C ..... +105°C\", \"value_ru\": \"-40°C ..... +105°C\