ru\": \"Материал корпуса\", \"value_en\": \"ABS\", \"value_ru\": \"ABS\"}, {\"title_en\": \"Connector\", \"title_ru\": \"Разъем\", \"value_en\": \"TYCO 828801-5\", \"value_ru\": \"TYCO 828801-5\"}, {\"title_en\": \"Place of installation\", \"title_ru\": \"Место установки\", \"value_en\": \"passenger compartment\", \"value_ru\": \"салон автомобиля\"}, {\"title_en\": \"IP degree of protection\", \"title_ru\": \"Степень защиты оболочки\", \"value_en\": \"IP4Х  according to GOST 14254\", \"value_ru\": \"IP4Х по ГОСТ 14254\"}, {\"title_en\": \"Operating temperature according to GOST 15150\", \"title_ru\": \"Рабочая температура ГОCТ 15150\", \"value_en\": \"-40°C ..... +85°C\", \"value_ru\": \"-40°C ..... +85°C\"}]',1,'2023-08-15 14:40:27','2024-06-24 09:39:04',NULL),(80,5,3,'Navigation multimedia system','Навигационная мультимедийная система','(Легк. тр-т)','<p><!--StartFragment-->Мультимедийная система предназначена для приема и воспроизведения радиовещания в диапазоне FM,  воспроизведения звуковых файлов с USB носителей и с мобильного телефона по протоколу Bluetooth A2DP через внешние акустические системы, а также отображения на дисплее изображения с камеры заднего вида и визуализации системы безопасной парковки.<!--EndFragment--></p>','<p><!--StartFragment-->Мультимедийная система предназначена для приема и воспроизведения радиовещания в диапазоне FM<!--EndFragment--></p>','<p><!--StartFragment-->The multimedia system is designed to receive and play FM radio broadcasts<!--EndFragment--></p>','<p><!--StartFragment-->The multimedia system is designed to receive and play FM radio broadcasts, play audio files from USB storage media and from a cell phone via Bluetooth A2DP through external speakers, as well as display images from the rear view camera and visualization of the safe parking system.<!--EndFragment--></p>','[{\"title_en\": \"FM radio signal playback\", \"title_ru\": \"Воспроизведение радиосигнала в диапазоне FM\"}, {\"title_en\": \"playback of media files from USB media\", \"title_ru\": \"Воспроизведение медиафайлов с USB носителей\"}, {\"title_en\": \"playback of the rear view camera signal\", \"title_ru\": \"Воспроизведение сигнала с камеры заднего вида\"}, {\"title_en\": \"visualization of safe parking system warnings\", \"title_ru\": \"Визуализация предупреждений системы безопасной парковки\"}, {\"title_en\": \"current time and date\", \"title_ru\": \"Указание текущего времени и даты\"}, {\"title_en\": \"overboard temperature\", \"title_ru\": \"Указание температуры за бортом\"}, {\"title_en\": \"Apple CarPlay and Android Auto support\", \"title_ru\": \"Поддержка Apple CarPlay и Android Auto\"}, {\"title_en\": \"hands-free phone calls\", \"title_ru\": \"Звонки с телефона в режиме hands-free\"}, {\"title_en\": \"media files playback via A2DP protocol\", \"title_ru\": \"Воспроизведение медиафайлов через протокол Bluetooth A2DP\"}, {\"title_en\": \"additional virtual annunciators\", \"title_ru\": \"Дополнительные виртуальные сигнализаторы\"}]','[{\"title_en\": \"Lada Vesta Ph2\", \"title_ru\": \"Lada Vesta Ph2\"}]','[{\"title_en\": \"Display type\", \"title_ru\": \"Тип дисплея\", \"value_en\": \"touch screen, IPS, 7\\\" diagonal (800х480)\", \"value_ru\": \"сенсорный, IPS, диагональ 7” (800х480)\"}, {\"title_en\": \"The layout type\", \"title_ru\": \"Тип компоновки\", \"value_en\": \"monoblock\", \"value_ru\": \"моноблок\"}, {\"title_en\": \"Interface\", \"title_ru\": \"Интерфейс\", \"value_en\": \"power connector, aerial connector, USB, peripheral connector (2 CAN, CVBS, microphone)\", \"value_ru\": \"разъём питания, разъём антенны, USB, разъём периферийный (2 CAN, CVBS, микрофон)\"}, {\"title_en\": \"Rated supply voltage\", \"title_ru\": \"Номинальное напряжение питания\", \"value_en\": \"12 V\", \"value_ru\": \"12 В\"}, {\"title_en\": \"Overall dimensions (LxWxH)\", \"title_ru\": \"Габаритные размеры (ДxШxВ)\", \"value_en\": \"184.2x154x137 mm\", \"value_ru\": \"184,2x154x137 мм\"}, {\"title_en\": \"Weight\", \"title_r