nt--></p>','<p><!--StartFragment-->Safe Parking System (SPS) is designed to warn the driver about various obstacles when the vehicle is maneuvering in the parking area and when moving in a multi-lane traffic.<!--EndFragment--></p>','[{\"title_en\": \"Alerting the driver on approaching an obstacle when the vehicle is backing out or moving forward at speeds of 0-10 km/h\", \"title_ru\": \"Предупреждение водителя о приближении к препятствию при движении автомобиля задним или передним ходом на скоростях 0-10км/ч\"}, {\"title_en\": \"In the version with blind spot monitoring function - Alerting the driver about the presence of an object in the vehicle\'s blind spot when driving in multi-lane traffic at speeds of 20-130 km/h.\", \"title_ru\": \"В варианте исполнения с функцией контроля слепых зон - Предупреждение водителя о наличии объекта в \\\"слепой зоне\\\" автомобиля при движении  в многорядном потоке на скоростях 20-130км/ч\"}]','[{\"title_en\": \"Largus\", \"title_ru\": \"Largus\"}, {\"title_en\": \"Vesta Ph.2\", \"title_ru\": \"Vesta Ph.2\"}, {\"title_en\": \"Granta FL\", \"title_ru\": \"Granta\"}, {\"title_en\": \"Gazelle NN\", \"title_ru\": \"Газель NN\"}]','[{\"title_en\": \"Number of connected sensors\", \"title_ru\": \"Количество подключаемых датчиков\", \"value_en\": \"3; 4; 8 pcs; In the version with blind spot monitoring - 12 pcs;\", \"value_ru\": \"3; 4; 8; 12 шт\"}, {\"title_en\": \"External buzzer\", \"title_ru\": \"Внешний зуммер\", \"value_en\": \"1 or 2 pcs (optional)\", \"value_ru\": \"1 или 2шт (опция)\"}, {\"title_en\": \"Alerting distance, parking\", \"title_ru\": \"Дистанция оповещения, парковка\", \"value_en\": \"0 - 250 cm\", \"value_ru\": \"0 – 250 см\"}, {\"title_en\": \"Alerting distance\", \"title_ru\": \"Дистанция оповещения\", \"value_en\": \"0 - 350 cm\", \"value_ru\": \"0 – 350 см\"}, {\"title_en\": \"blind spots\", \"title_ru\": \"Слепые зон\", \"value_en\": \"0 - 350 cm\", \"value_ru\": \"0 – 350 см\"}, {\"title_en\": \"Scanning cycl