>','<p><!--StartFragment-->Система «Медиа-информирование на транспорте» предназначена для предоставления пассажирам маршрутной информации и данных о работе НГПТ, а также организации эффективных рекламных кампаний.<!--EndFragment--></p>',NULL,NULL,'[{\"title_en\": null, \"title_ru\": \"Ультраширокая матрица формата 16:4,5 позволяет размещать рекламный и/или информационный контент, не прерывая режим визуализации текущих остановок и местоположения транспортного средства на маршруте\"}, {\"title_en\": null, \"title_ru\": \"Оптимальные габаритные размеры, позволяющие обеспечить свободный проход пассажиров по салону транспортного средства\"}, {\"title_en\": null, \"title_ru\": \"Вандалозащищенный корпус, устойчивый к воздействию извне\"}, {\"title_en\": null, \"title_ru\": \"Расписание показа контента для каждого экрана/группы экранов сети формируется отдельно.\"}, {\"title_en\": null, \"title_ru\": \"В случае чрезвычайной ситуации, при получении сигнала МЧС, информация оперативно выводится на все экраны сети системы медиа-информирования. Плановое вещание прерывается вручную или автоматически.\"}, {\"title_en\": null, \"title_ru\": \"Возможность интеграции со сторонними информационными системами\"}, {\"title_en\": null, \"title_ru\": \"Информирование пассажиров происходит с учетом геопозиции ТС — автоматически воспроизводится информация о маршруте, текущей и следующей остановках, а также информация рекламного и/или информационного характера\"}, {\"title_en\": null, \"title_ru\": \"Автоматическое создание отчетов о количестве и времени выхода рекламного и/или информационного контента за определенный промежуток времени по ролику/группе роликов.\"}]','[]','[{\"title_en\": null, \"title_ru\": \"Медиапанель ТРАНСТЕЛЕМ-2860 в алюминиевом корпусе СВТГ.467221.034\", \"value_en\": null, \"value_ru\": null}, {\"title_en\": null, \"title_ru\": \"Медиапанель ТРАНСТЕЛЕМ-3700 СВТГ.467221.037\", \"value_en\": null, \"value_ru\": null}]',1,'2023-08-18 07:24:58','2023-09-15 05:46:08',NULL