{\"title_en\": null, \"title_ru\": \"УАЗ ПРОФИ\"}, {\"title_en\": null, \"title_ru\": \"УАЗ ПАТРИОТ\"}]','[{\"title_en\": null, \"title_ru\": \"Ключевые особенности изделия\", \"value_en\": null, \"value_ru\": \"с выкидным лезвием, с фиксированны лезвием\"}, {\"title_en\": null, \"title_ru\": \"Тип сигнала\", \"value_en\": null, \"value_ru\": \"125 кГц - иммобилайзерный канал, 433 МГц - радиоканал дальнего действия\"}, {\"title_en\": null, \"title_ru\": \"Доступные варианты реализации системы доступа в автомобиль\", \"value_en\": null, \"value_ru\": \"RKE, PKE\"}, {\"title_en\": null, \"title_ru\": \"Габаритные размеры (ДxШxВ)\", \"value_en\": null, \"value_ru\": \"с выкидным лезвием - 64,3x35,2x19 мм; с фиксированны лезвием - 50x40x19 мм\"}, {\"title_en\": null, \"title_ru\": \"Материал корпуса\", \"value_en\": null, \"value_ru\": \"с выкидным лезвием - PBT; с фиксированны лезвием - PA\"}, {\"title_en\": null, \"title_ru\": \"Вес\", \"value_en\": null, \"value_ru\": \"с выкидным лезвием - 0,044 кг; с фиксированны лезвием - 0,024 кг\"}, {\"title_en\": null, \"title_ru\": \"Рабочая температура по ГОCТ 15150\", \"value_en\": null, \"value_ru\": \"-40°C ..... +85°C\"}]',1,'2023-08-23 04:28:09','2024-06-24 09:39:00',NULL),(178,2,2,'Oxygen sensor','Датчик концентрации кислорода','(Легк. тр-т)','<p><!--StartFragment-->Датчик концентрации кислорода (лямбда-зонд) устанавливается в выпускной системе и предназначен для определения в отработавших газах наличия остаточного кислорода. На основе этой информации контроллер системы управления двигателем выполняет коррекцию топливоподачи с целью обеспечения оптимального режима работы трехкомпонентного каталитического нейтрализатора и выполнения требуемых норм по токсичности.<!--EndFragment--></p>','<p><!--StartFragment-->Датчик концентрации кислорода (лямбда-зонд) устанавливается в выпускной системе и предназначен для определения в отработавших газах наличия остаточного кислорода<!--EndFragment--></p>','<p><!--StartFragment-->The oxygen sensor (lambda probe) is installed in the exhaust system and is designed to detect the presence of residual oxygen in the exhaust gases<!--EndFragment--></p>','<p><!--StartFragment-->The oxygen sensor (lambda probe) is installed in the exhaust system and is designed to detect the presence of residual oxygen in the exhaust gases. Based on this information, the engine management system controller adjusts the fuel supply to ensure optimal operation for the three-way catalytic converter and to meet the required emission standards.<!--EndFragment--></p>','[]','[{\"title_en\": \"Granta\", \"title_ru\": \"Granta\"}, {\"title_en\": \"Vesta\", \"title_ru\": \"Vesta\"}, {\"title_en\": \"Largus\", \"title_ru\": \"Largus\"}, {\"title_en\": \"GAZ\", \"title_ru\": \"ГАЗ\"}]','[{\"title_en\": \"Key features of the item\", \"title_ru\": \"Ключевые особенности изделия\", \"value_en\": \"A separate chamber with reference air is not required\", \"value_ru\": \"Не требуется отдельная камера с референсным воздухом\"}, {\"title_en\": \"Sensor type\", \"title_ru\": \"Тип датчика\", \"value_en\": \"Relay-type\", \"value_ru\": \"Релейного типа\"}, {\"title_en\": \"The type of sensing element\", \"title_ru\": \"Тип чувствительного элемента\", \"value_en\": \"Is zirconium dioxide\", \"value_ru\": \"Двуокись циркония\"}, {\"title_en\": \"Pump current value\", \"title_ru\": \"Значение тока накачки\", \"value_en\": \"7...13 µA / ≤ 5 V\", \"value_ru\": \"7...13 мкА / ≤ 5 В\"}, {\"title_en\": \"Heater supply voltage\", \"title_ru\": \"Напряжение питания нагревателя\", \"value_en\": \"10...18 V / 13.5 V nom. / 21 V @ < 60 c 21°C\", \"value_ru\": \"10..18 В / 13,5 В ном. / 21 В @ < 60 c 21°C\"}, {\"title_en\": \"Heater resistance\", \"title_ru\": \"Сопротивление нагревателя\", \"value_en\": \"9.6 Ohm @ 21°C\", \"value_ru\": \"9,6 Ом @ 21°C\"}, {\"title_en\": \"Heater control\", \"title_ru\": \"Управление нагревателем\", \"value_en\": \"PWM ≥ 10 Hz\", \"value_ru\": \"ШИМ ≥ 10 Гц\"}, {\"title_en\": \"Maximum inrush current\", \"title_ru\": \"Максимальный пусковой ток\", \"value_en\": \"≤ 2.2 A @ -40°C\", \"value_ru\": \"≤ 2,2 A @ -40°C\"}, {\"title_en\": \"Availability time (after dew point)\", \"title_ru\": \"Время готовности (после точки росы)\", \"value_en\": \"From 9.8 s\", \"value_ru\": \"от 9,8 с\"}, {\"title_en\": \"Overall dimensions (LxWxH)\", \"title_ru\": \"Габаритные размеры (ДxШxВ)\", \"value_en\": \"459x26x26 mm\", \"value_ru\": \"459x26x26 мм\"}, {\"title_en\": \"Weight\", \"title_ru\": \"Вес\", \"value_en\": \"1.08 kg\", \"value_ru\": \"0,08 кг\"}, {\"title_en\": \"Body material\", \"title_ru\": \"Материал корпуса\", \"value_en\": \"Stainless steel (body and tip)\", \"value_ru\": \"Нержавеющая сталь (корпус и наконечник)\"}, {\"title_en\": \"Connector\", \"title_ru\": \"Разъем\", \"value_en\": \"BOSCH 1-928-403-453; 1-928-403-913; 1-928-403-189\", \"value_ru\": \"BOSCH 1-928-403-453; 1-928-403-913; 1-928-403-189\"}, {\"title_en\": \"Place of installation\", \"title_ru\": \"Место установки\", \"value_en\": \"Exhaust system\", \"value_ru\": \"выпускная система\"}, {\"title_en\": \"Operating temperature according to\", \"title_ru\": \"Рабочая температура по\", \"value_en\": \"GOST 15150\", \"value_ru\": \"ГОCТ 15150\"}]',1,'2023-08-23 07:19:50','2024-01-12 09:17:36',NULL),(179,2,0,'Absolute pressure and air temperature sensor','Датчик абсолютного давления и температуры воздуха','(Легк. тр-т)','<p><!--StartFragment-->ДАД предназначен для измерения давления и температуры воздуха в модуле впуска. На основе этой информации контроллер системы управления двигателем выполняет оценку количества воздуха, поступающего в цилиндры во время такта впуска.<!--EndFragment--></p>','<p><!--StartFragment-->ДАД предназначен для измерения давления и температуры воздуха в модуле впуска<!--EndFragment--></p>','<p><!--StartFragment-->The absolute pressure sensor (APS) is designed to measure air pressure and temperature in the intake module<!--EndFragment--></p>','<p><!--StartFragment-->The absolute pressure sensor (APS) is designed to measure air pressure and temperature in the intake module. Based on this information, the engine management system controller makes an estimate of the amount of air entering the cylinders during the induction stroke.<!--EndFragment--></p>','[{\"title_en\": \"Measuring the air pressure in the intake module\", \"title_ru\": \"Измерение давления  воздуха в модуле впуска\"}, {\"title_en\": \"Measuring the air temperature in the intake module\", \"title_ru\": \"Измерение температуры воздуха в модуле впуска\"}]','[{\"title_en\": \"Granta FL\", \"title_ru\": \"Granta FL\"}, {\"title_en\": \"Vesta\", \"title_ru\": \"Vesta\"}, {\"title_en\": \"Largus\", \"title_ru\": \"Largus\"}]','[{\"title_en\": \"Key features of the item\", \"title_ru\": \"Ключевые особенности изделия\", \"value_en\": \"Low performance spread of the pressure sensor (±1.6%); High stability of the performance over the life cycle (±2.4%)\", \"value_ru\": \"Низкий разброс характерики датчика давления (±1,6%); высокая стабильность характеристики в жизненном цикле (±2,4%)\"}, {\"title_en\": \"Operating pressure range\", \"title_ru\": \"Диапазон рабочих давлений\", \"value_en\": \"(10...115)±1.6 kPa\", \"value_ru\": \"(10…115)±1,6 кПа\"}, {\"title_en\": \"Time constant\", \"title_ru\": \"Постоянная времени\", \"value_en\": \"Less than 5ms\", \"value_ru\": \"менее 5мс\"}, {\"title_en\": \"The range of temperatures to be measured\", \"title_ru\": \"Диапазон измеряемых температур\", \"value_en\": \"Is -40°C ..... +125°C\", \"value_ru\": \"-40°C ..... +125°C\"}, {\"title_en\": \"Supply voltage\", \"title_ru\": \"Напряжение питания\", \"value_en\": \"4.9...5.1 V\", \"value_ru\": \"4,9…5,1 В\"}, {\"title_en\": \"Overall dimensions (LxWxH)\", \"title_ru\": \"Габаритные размеры (ДxШxВ)\", \"value_en\": \"59.5x28x42.4 mm\", \"value_ru\": \"59,5x28x42,4 мм\"}, {\"title_en\": \"Weight\", \"title_ru\": \"Вес\", \"value_en\": \"0.027 kg\", \"value_ru\": \"0,027 кг\"}, {\"title_en\": \"Body material\", \"title_ru\": \"Материал корпуса\", \"value_en\": \"PBT-GF30\", \"value_ru\": \"PBT-GF30\"}, {\"title_en\": \"Connector\", \"title_ru\": \"Разъем\", \"value_en\": \"Must mate with Delphi 15397339 or 15439906 Code 1, it is allowed to use terminal block BOSCH 1 928 403 112 for connection\", \"value_ru\": \"должен сопрягается с Delphi 15397339 или 15439906 code 1, допускается применять для соединения колодку BOSCH 1 928 403 112\"}, {\"title_en\": \"Place of installation\", \"title_ru\": \"Место установки\", \"value_en\": \"Engine compartment\", \"value_ru\": \"моторный отсек\"}, {\"title_en\": \"IP degree of protection\", \"title_ru\": \"Степень защиты оболочки\", \"value_en\": \"IP6K9K GOST 14254\", \"value_ru\": \"IP6K9K ГОСТ 14254\"}, {\"title_en\": \"Operating temperature according to GOST 15150\", \"title_ru\": \"Рабочая температура по ГОCТ 15150\", \"value_en\": \"-40°C ..... +125°C\", \"value_ru\": \"-40°C ..... +125°C\"}]',1,'2023-08-23 07:29:28','2024-01-10 09:53:28',NULL),(180,4,14,'Стеклоподъемники (Легк. тр-т)','Стеклоподъемники','(Легк. тр-т)','<p><!--StartFragment-->Стеклоподъемники  служат для перемещения стекла передней двери вверх и вниз с помощью моторедуктора. \r\nСостоят из различных компонентов, собранных вместе на специальном сборочном оборудовании. А именно: прокатные направляющие, кронштейны, болты, ролики, заклепки, моторедуктор, боуденовский трос, ползуны-держатели стекла, барабан намотки троса и его корпус-крышка. Фиксация посредствам вворачиванием винта в корпус-крышку барабана намотки троса. Все упомянутые компоненты в собранном виде обеспечивают данным стеклоподъемникам возможность выполнять их непосредственную функцию – открытие и закрытие окна автомобиля. <!--EndFragment--></p>','<p><!--StartFragment-->Стеклоподъемники  служат для перемещения стекла передней двери вверх и вниз с помощью моторедуктора<!--EndFragment--></p>',NULL,NULL,'[{\"title_en\": null, \"title_ru\": \"Перемещение стекла передней двери вверх и вниз с помощью моторедуктора\"}]','[{\"title_en\": null, \"title_ru\": \"Веста\"}, {\"title_en\": null, \"title_ru\": \"Гранта\"}, {\"title_en\": null, \"title_ru\": \"Нива\"}]','[{\"title_en\": null, \"title_ru\": \"Ключевые особенности изделия\", \"value_en\": null, \"value_ru\": \"мотор электрический, постоянного тока\"}, {\"title_en\": null, \"title_ru\": \"Крутящий момент\", \"value_en\": null, \"value_ru\": \"7.5 NM-11.9NM\"}, {\"title_en\": null, \"title_ru\": \"Рабочий ток\", \"value_en\": null, \"value_ru\": \"2,5А\"}, {\"title_en\": null, \"title_ru\": \"Ток блокировки\", \"value_en\": null, \"value_ru\": \"29А\"}, {\"title_en\": null, \"title_ru\": \"Электрическая входная мощность\", \"value_en\": null, \"value_ru\": \"30Вт\"}, {\"title_en\": null, \"title_ru\": \"Электрическая выходная мощность (рабочая) номинальная\", \"value_en\": null, \"value_ru\": \"65Вт\"}, {\"title_en\": null, \"title_ru\": \"Электрическая входная мощность (блокировки) максимальная\", \"value_en\": null, \"value_ru\": \"230Вт\"}, {\"title_en\": null, \"title_ru\": \"Электрическая выходная мощность (блокировки) максимальная\", \"value_en\": null, \"value_ru\": \"30Вт\"}, {\"title_en\": null, \"title_ru\": \"Напряжение\", \"value_en\": null, \"value_ru\": \"12В\"}]',1,'2023-08-23 07:49:44','2024-06-24 09:39:00',NULL),(181,4,13,'Understeering switches','Подрулевые переключатели с датчиком угла поворота','(Легк. тр-т)','<p><!--StartFragment-->Модуль подрулевых переключателей с датчиком&nbsp;<!--StartFragment-->угла поворота рулевого колеса<!--EndFragment--></p>','<p><!--StartFragment--><span data-sheets-value=\"{\" 1\":2,\"2\":\"Модуль=\"\" подрулевых=\"\" переключателей\"}\"=\"\" data-sheets-userformat=\"{\" 2\":15339,\"3\":{\"1\":0},\"4\":{\"1\":2,\"2\":16776960},\"6\":{\"1\":[{\"1\":2,\"2\":0,\"5\":{\"1\":2,\"2\":0}},{\"1\":0,\"2\":0,\"3\":3},{\"1\":1,\"2\":0,\"4\":1}]},\"8\":{\"1\":[{\"1\":2,\"2\":0,\"5\":{\"1\":2,\"2\":0}},{\"1\":0,\"2\":0,\"3\":3},{\"1\":1,\"2\":0,\"4\":1}]},\"9\":0,\"10\":0,\"11\":4,\"12\":0,\"14\":{\"1\":2,\"2\":0},\"15\":\"calibri,=\"\" sans-serif\",\"16\":11}\"=\"\">Модуль подрулевых переключателей с датчиком&nbsp;<!--StartFragment-->угла поворота рулевого колеса<!--EndFragment--></span><!--EndFragment--></p>','<p><!--StartFragment-->Understeering switches module<!--EndFragment--></p>',NULL,'[{\"title_en\": \"Controls for various electrical instruments and systems in the vehicle, made as levers and mounted on the steering column under the steering wheel. Understeering switches are used to control those electrical instruments and systems of the vehicle that are frequently used while driving - turn indicators, head lights, marker lights and other lighting devices, wipers and washers, horn.\", \"title_ru\": \"Органы управления различными электрическими приборами и системами автомобиля, выполненные в виде рычагов и установленные на рулевой колонке под рулевым колесом. Подрулевые переключатели используются для управления теми электрическими приборами и системами автомобиля, которые часто используются во время движения — указателями поворота, головным светом, габаритными огнями и прочей светотехникой, стеклоочистителями и стеклоомывателями, звуковым сигналом.\"}, {\"title_en\": null, \"title_ru\": \"Измерительный преобразователь угла поворота рулевого колеса в цифровые сигналы, которые позволяют определить угол его поворота.\"}]','[{\"title_en\": \"Vesta\", \"title_ru\": \"Веста\"}]','[]',1,'2023-08-23 07:56:19','2024-06-24 09:39:00',NULL),(182,5,5,'Shark fin antenna','Антенна-плавник','(Легк. тр-т)','<p><!--StartFragment--><span data-sheets-value=\"{\" 1\":2,\"2\":\"fm+gnss=\"\" антенна=\"\" (акулий=\"\" плавник)\"}\"=\"\" data-sheets-userformat=\"{\" 2\":15339,\"3\":{\"1\":0},\"4\":{\"1\":2,\"2\":16776960},\"6\":{\"1\":[{\"1\":2,\"2\":0,\"5\":{\"1\":2,\"2\":0}},{\"1\":0,\"2\":0,\"3\":3},{\"1\":1,\"2\":0,\"4\":1}]},\"8\":{\"1\":[{\"1\":2,\"2\":0,\"5\":{\"1\":2,\"2\":0}},{\"1\":0,\"2\":0,\"3\":3},{\"1\":1,\"2\":0,\"4\":1}]},\"9\":0,\"10\":0,\"11\":4,\"12\":0,\"14\":{\"1\":2,\"2\":0},\"15\":\"calibri,=\"\" sans-serif\",\"16\":11}\"=\"\">FM+GNSS антенна (акулий плавник)</span><!--EndFragment--></p>','<p><!--StartFragment--><span data-sheets-value=\"{\" 1\":2,\"2\":\"fm+gnss=\"\" антенна=\"\" (акулий=\"\" плавник)\"}\"=\"\" data-sheets-userformat=\"{\" 2\":15339,\"3\":{\"1\":0},\"4\":{\"1\":2,\"2\":16776960},\"6\":{\"1\":[{\"1\":2,\"2\":0,\"5\":{\"1\":2,\"2\":0}},{\"1\":0,\"2\":0,\"3\":3},{\"1\":1,\"2\":0,\"4\":1}]},\"8\":{\"1\":[{\"1\":2,\"2\":0,\"5\":{\"1\":2,\"2\":0}},{\"1\":0,\"2\":0,\"3\":3},{\"1\":1,\"2\":0,\"4\":1}]},\"9\":0,\"10\":0,\"11\":4,\"12\":0,\"14\":{\"1\":2,\"2\":0},\"15\":\"calibri,=\"\" sans-serif\",\"16\":11}\"=\"\">FM+GNSS антенна (акулий плавник)</span><!--EndFragment--></p>','<p><!--StartFragment-->FM+GNSS antenna (shark fin)<!--EndFragment--></p>','<p><!--StartFragment-->FM+GNSS antenna (shark fin)<!--EndFragment--></p>','[{\"title_en\": \"FM antenna - a device designed to receive radio waves.\", \"title_ru\": \"FM антенна - устройство, предназначенное для приёма радиоволн\"}, {\"title_en\": \"Glonass (GNSS) - a device designed to receive, pre-process signals received from artificial Earth satellites. They show location (coordinates, radius), direction, velocity of any static, dynamic objects.\", \"title_ru\": \"Glonass (GNSS) - устройство предназначено для приема, предварительной обработки сигналов, получаемых от искусственных спутников Земли. Показывают местонахождение (координаты, радиус), направление, скорость любых статических, динамических объектов\"}]','[{\"title_en\": \"Vesta\", \"title_ru\": \"Веста\"}]','[]',1,'2023-08-23 08:02:22','2024-06-24 09:39:47',NULL),(183,10,0,'EPS','Усилитель электромеханический рулевого управления','(Легк. тр-т)','<p><!--StartFragment--><span data-sheets-value=\"{\" 1\":2,\"2\":\"Электроусилитель=\"\" руля\"}\"=\"\" data-sheets-userformat=\"{\" 2\":15339,\"3\":{\"1\":0},\"4\":{\"1\":2,\"2\":16776960},\"6\":{\"1\":[{\"1\":2,\"2\":0,\"5\":{\"1\":2,\"2\":0}},{\"1\":0,\"2\":0,\"3\":3},{\"1\":1,\"2\":0,\"4\":1}]},\"8\":{\"1\":[{\"1\":2,\"2\":0,\"5\":{\"1\":2,\"2\":0}},{\"1\":0,\"2\":0,\"3\":3},{\"1\":1,\"2\":0,\"4\":1}]},\"9\":0,\"10\":0,\"11\":4,\"12\":0,\"14\":{\"1\":2,\"2\":0},\"15\":\"calibri,=\"\" sans-serif\",\"16\":11}\"=\"\">Электроусилитель руля</span><!--EndFragment--></p>','<p><!--StartFragment--><span data-sheets-value=\"{\" 1\":2,\"2\":\"Электроусилитель=\"\" руля\"}\"=\"\" data-sheets-userformat=\"{\" 2\":15339,\"3\":{\"1\":0},\"4\":{\"1\":2,\"2\":16776960},\"6\":{\"1\":[{\"1\":2,\"2\":0,\"5\":{\"1\":2,\"2\":0}},{\"1\":0,\"2\":0,\"3\":3},{\"1\":1,\"2\":0,\"4\":1}]},\"8\":{\"1\":[{\"1\":2,\"2\":0,\"5\":{\"1\":2,\"2\":0}},{\"1\":0,\"2\":0,\"3\":3},{\"1\":1,\"2\":0,\"4\":1}]},\"9\":0,\"10\":0,\"11\":4,\"12\":0,\"14\":{\"1\":2,\"2\":0},\"15\":\"calibri,=\"\" sans-serif\",\"16\":11}\"=\"\">Электроусилитель руля</span><!--EndFragment--></p>','<p><!--StartFragment-->Electric power steering<!--EndFragment--></p>','<p><!--StartFragment-->Electric power steering<!--EndFragment--></p>','[{\"title_en\": \"The vehicle electromechanical system designed to reduce the steering effort applied to the steering wheel.\", \"title_ru\": \"Электромеханическая система автомобиля, предназначенная для снижения управляющего усилия, прикладываемого к рулевому колесу.\"}]','[{\"title_en\": \"Vesta\", \"title_ru\": \"Веста\"}]','[]',1,'2023-08-23 08:25:19','2024-01-11 20:41:32',NULL),(184,10,0,'Anti-lock braking system (ABS) unit for motor vehicles','AБС (Блок антиблокировочной системы колес для легковых автомобилей)','(Легк. тр-т)','<p><!--StartFragment--><span data-sheets-value=\"{\" 1\":2,\"2\":\"Блок=\"\" антиблокировочной=\"\" системы=\"\" колес=\"\" для=\"\" легковых=\"\" автомобилей=\"\" с=\"\" цифровым=\"\" управлением=\"\" клапанами=\"\" и=\"\" двухпоршневым=\"\" насосом,=\"\" предназначен=\"\" работы=\"\" в=\"\" составе=\"\" (АБС),=\"\" которая=\"\" свою=\"\" очередь=\"\" является=\"\" активной=\"\" системой=\"\" безопасности,=\"\" предотвращает=\"\" блокировку=\"\" потерю=\"\" устойчивости=\"\" управляемости=\"\" автомобилем=\"\" во=\"\" время=\"\" торможения,=\"\" автоматически=\"\" регулирует=\"\" давление=\"\" тормозной=\"\" жидкости=\"\" тормозных=\"\" цилиндрах\"}\"=\"\" data-sheets-userformat=\"{\" 2\":343039,\"3\":{\"1\":0},\"4\":{\"1\":2,\"2\":16776960},\"5\":{\"1\":[{\"1\":2,\"2\":0,\"5\":{\"1\":2,\"2\":0}},{\"1\":0,\"2\":0,\"3\":3},{\"1\":1,\"2\":0,\"4\":1}]},\"6\":{\"1\":[{\"1\":2,\"2\":0,\"5\":{\"1\":2,\"2\":0}},{\"1\":0,\"2\":0,\"3\":3},{\"1\":1,\"2\":0,\"4\":1}]},\"7\":{\"1\":[{\"1\":2,\"2\":0,\"5\":{\"1\":2,\"2\":0}},{\"1\":0,\"2\":0,\"3\":3},{\"1\":1,\"2\":0,\"4\":1}]},\"8\":{\"1\":[{\"1\":2,\"2\":0,\"5\":{\"1\":2,\"2\":0}},{\"1\":0,\"2\":0,\"3\":3},{\"1\":1,\"2\":0,\"4\":1}]},\"9\":0,\"10\":0,\"11\":4,\"12\":0,\"14\":{\"1\":3,\"3\":1},\"15\":\"calibri\",\"16\":11,\"19\":0,\"21\":1}\"=\"\">Блок антиблокировочной системы колес для легковых автомобилей  с цифровым управлением клапанами и двухпоршневым насосом, предназначен для работы в составе антиблокировочной системы (АБС), которая в свою очередь является активной системой безопасности, которая предотвращает блокировку колес и потерю устойчивости и управляемости автомобилем во время торможения, автоматически регулирует давление тормозной жидкости в тормозных цилиндрах</span><!--EndFragment--></p>','<p><!--StartFragment-->Блок антиблокировочной системы колес для легковых автомобилей  с цифровым управлением клапанами и двухпоршневым насосом<!--EndFragment--></p>','<p><!--StartFragment-->Anti-lock braking system unit for motor cars with digital valve control and two-piston pump<!--EndFragment--></p>','<p><!--StartFragment-->Anti-lock braking system unit for motor cars with digital valve control and two-piston pump, designed to work as part of the anti-lock braking system (ABS), which in its turn is an active safety system that prevents wheel locking and instability and steerability loss of the vehicle during braking, automatically adjusts the pressure of brake fluid in the brake cylinders<!--EndFragment--></p>','[{\"title_en\": \"during emergency braking, the anti-lock braking system (ABS)  adjusts the brake pressure on the 4 wheels to prevent wheel lockup and ensure vehicle stability\", \"title_ru\": \"Антиблокировочная тормозная система (ABS) в процессе экстренного торможения регулирует тормозное давление на 4 колесах чтобы предотвратить блокировку колес и обеспечить устойчивость автомобиля\"}, {\"title_en\": \"It allows for efficient use of the the tire grip on the pavement to reduce braking distances\", \"title_ru\": \"Позволяет эффективно использовать сцепление шины с дорожным покрытием для сокращения тормозного пути\"}, {\"title_en\": \"It provides steerability, prevents the rear wheels from sideways skidding and improves lateral stability\", \"title_ru\": \"Обеспечивает управляемость, предотвращает боковое скольжение задних колес и улучшает боковую устойчивость\"}, {\"title_en\": \"It reduces tire wear and increases its service life\", \"title_ru\": \"Уменьшает износ шин и увеличивает срок их службы\"}, {\"title_en\": \"Electronic Brake-force Distribution (EBD) depending on the axle load distribution when braking the vehicle and the grip conditions of the wheels, automatically adjusts the braking force on the front and rear axles to improve braking efficiency and braking stability as well as lateral stability; It efficiently complements and enhances the performance of the ABS function.\", \"title_ru\": \"Электронное распределение тормозных усилий (EBD) в зависимости от распределения нагрузки на ось при торможении транспортного средства и условий сцепления колес с дорогой, автоматически регулирует тормозное усилие на передней и задней осях для повышения эффективности и стабильности торможения, а также для улучшения боковой устойчивости; эффективно дополняет и повышает эффективность функции ABS\"}]','[{\"title_en\": \"Vesta\", \"title_ru\": \"Vesta\"}, {\"title_en\": \"Granta\", \"title_ru\": \"Granta\"}, {\"title_en\": \"Niva Legend\", \"title_ru\": \"Niva Legend\"}, {\"title_en\": \"Niva Trevel\", \"title_ru\": \"Niva Trevel\"}, {\"title_en\": \"XJO\", \"title_ru\": \"XJO\"}, {\"title_en\": \"HGH\", \"title_ru\": \"HGH\"}]','[{\"title_en\": \"Key features of the item\", \"title_ru\": \"Ключевые особенности изделия\", \"value_en\": \"ABS, EBD functions\", \"value_ru\": \"функции ABS, EBD\"}, {\"title_en\": \"Type of hydraulic circuit\", \"title_ru\": \"Тип гидравлической схемы\", \"value_en\": \"X\", \"value_ru\": \"Х\"}, {\"title_en\": \"The rated voltage of the onboard network\", \"title_ru\": \"Номинальное напряжение бортовой сети\", \"value_en\": \"12V\", \"value_ru\": \"12В\"}, {\"title_en\": \"Communication\", \"title_ru\": \"Коммуникация\", \"value_en\": \"1 CAN channel\", \"value_ru\": \"1 канал CAN\"}, {\"title_en\": \"Diagnostics\", \"title_ru\": \"Диагностика\", \"value_en\": \"UDS on CAN (ISO 15765)\", \"value_ru\": \"UDS on CAN (ISO 15765)\"}, {\"title_en\": \"Additional functions\", \"title_ru\": \"Дополнительные функции\", \"value_en\": \"EOL implementation\", \"value_ru\": \"реализация EOL\"}, {\"title_en\": \"Overall dimensions (LxWxH)\", \"title_ru\": \"Габаритные размеры (ДxШxВ)\", \"value_en\": \"125.7x84.2x115 mm\", \"value_ru\": \"125,7x84,2x115 мм\"}, {\"title_en\": \"Weight\", \"title_ru\": \"Вес\", \"value_en\": \"1.37 kg\", \"value_ru\": \"1,37 кг\"}, {\"title_en\": \"Body material\", \"title_ru\": \"Материал корпуса\", \"value_en\": \"aluminum alloy, plastic PBT GF-30\", \"value_ru\": \"аллюминиевый сплав, пластик PBT GF-30\"}, {\"title_en\": \"Connector\", \"title_ru\": \"Разъем\", \"value_en\": \"TE 1-2112502-1 (38 pins)\", \"value_ru\": \"TE 1-2112502-1 (38 контактов)\"}, {\"title_en\": \"Place of installation\", \"title_ru\": \"Место установки\", \"value_en\": \"engine compartment\", \"value_ru\": \"моторный отсек\"}, {\"title_en\": \"IP degree of protection\", \"title_ru\": \"Степень защиты оболочки\", \"value_en\": \"IP67 GOST 14254\", \"value_ru\": \"IP67 ГОСТ 14254\"}, {\"title_en\": \"Operating temperature according to GOST 15150\", \"title_ru\": \"Рабочая температура по ГОCТ 15150\", \"value_en\": \"-40°C ..... +110°C\", \"value_ru\": \"-40°C ..... +110°C\"}]',1,'2023-08-23 08:36:40','2024-01-11 18:20:56',NULL),(185,5,6,'Мультимедийная система (Комм. тр-т)','Мультимедийная система','(Комм. тр-т)','<p><!--StartFragment--><span data-sheets-value=\"{\" 1\":2,\"2\":\"Мультимедийная=\"\" система=\"\" предназначена=\"\" для=\"\" приема=\"\" и=\"\" воспроизведения=\"\" радиовещания=\"\" в=\"\" диапазонах=\"\" am=\"\" fm,=\"\" звуковых=\"\" файлов=\"\" с=\"\" usb=\"\" носителей=\"\" модильного=\"\" телефона=\"\" по=\"\" протоколу=\"\" bluetooth,=\"\" через=\"\" внешние=\"\" акустические=\"\" системы,=\"\" отображения=\"\" на=\"\" дисплее=\"\" навигационной=\"\" информации=\"\" изображения=\"\" камеры=\"\" заднего=\"\" вида.\"}\"=\"\" data-sheets-userformat=\"{\" 2\":14847,\"3\":{\"1\":0,\"3\":1},\"4\":{\"1\":2,\"2\":16776960},\"5\":{\"1\":[{\"1\":2,\"2\":0,\"5\":{\"1\":2,\"2\":0}},{\"1\":0,\"2\":0,\"3\":3},{\"1\":1,\"2\":0,\"4\":1}]},\"6\":{\"1\":[{\"1\":2,\"2\":0,\"5\":{\"1\":2,\"2\":0}},{\"1\":0,\"2\":0,\"3\":3},{\"1\":1,\"2\":0,\"4\":1}]},\"7\":{\"1\":[{\"1\":2,\"2\":0,\"5\":{\"1\":2,\"2\":0}},{\"1\":0,\"2\":0,\"3\":3},{\"1\":1,\"2\":0,\"4\":1}]},\"8\":{\"1\":[{\"1\":2,\"2\":0,\"5\":{\"1\":2,\"2\":0}},{\"1\":0,\"2\":0,\"3\":3},{\"1\":1,\"2\":0,\"4\":1}]},\"9\":0,\"10\":0,\"11\":4,\"14\":{\"1\":3,\"3\":1},\"15\":\"calibri\",\"16\":10}\"=\"\">Мультимедийная система предназначена для приема и воспроизведения  радиовещания в диапазонах AM/FM, воспроизведения звуковых файлов с USB носителей и модильного телефона по протоколу Bluetooth, через внешние акустические системы, для отображения на дисплее навигационной информации и изображения с камеры заднего вида.</span><!--EndFragment--></p>','<p><!--StartFragment-->Мультимедийная система предназначена для приема и воспроизведения  радиовещания в диапазонах AM/FM, воспроизведения звуковых файлов с USB носителей...<!--EndFragment--></p>',NULL,NULL,'[{\"title_en\": null, \"title_ru\": \"Воспроизведение радиосигнала в диапазоне АМ/FM\"}, {\"title_en\": null, \"title_ru\": \"Ввоспроизведение радиосигнала в диапазоне АМ/FM\"}, {\"title_en\": null, \"title_ru\": \"Воспроизведение изображения с камеры заднего вида / системы кругового обзора с визуализацией предупреждений системы безопасной парковки\"}, {\"title_en\": null, \"title_ru\": \"Текущее время и дата\"}, {\"title_en\": null, \"title_ru\": \"Поддержка функции \\\"зеркалирования\\\" экрана телефона на экране ММС\"}, {\"title_en\": null, \"title_ru\": \"Звонки с телефона в режиме hands-free\"}, {\"title_en\": null, \"title_ru\": \"Воспроизведение медиафайлов через протокол A2DP\"}, {\"title_en\": null, \"title_ru\": \"Навигационное ПО НАВИТЕЛ с предустановленными картами России и возможностью загрузки дополнительных карт\"}, {\"title_en\": null, \"title_ru\": \"Дополнительные специализированное ПО\"}]','[]','[{\"title_en\": null, \"title_ru\": \"Тип компоновки\", \"value_en\": null, \"value_ru\": \"моноблок\"}, {\"title_en\": null, \"title_ru\": \"Тип дисплея\", \"value_en\": null, \"value_ru\": \"сенсорный цветной TFT, диагональ 9” (1280х720)\"}, {\"title_en\": null, \"title_ru\": \"Интерфейс\", \"value_en\": null, \"value_ru\": \"1 CAN (диагностический, автомобильный), 2xUSB, разъём питания, разъём антенны\"}, {\"title_en\": null, \"title_ru\": \"Номинальное напряжение питания\", \"value_en\": null, \"value_ru\": \"12 В\"}, {\"title_en\": null, \"title_ru\": \"Габаритные размеры (ДxШxВ)\", \"value_en\": null, \"value_ru\": \"273,2x225,3x154,1 мм\"}, {\"title_en\": null, \"title_ru\": \"Вес\", \"value_en\": null, \"value_ru\": \"1,8 кг\"}, {\"title_en\": null, \"title_ru\": \"Материалы\", \"value_en\": null, \"value_ru\": \"сталь, алюминиевый сплав (шасси), ABS (корпус, декоративная рамка)\"