2\":0}},{\"1\":0,\"2\":0,\"3\":3},{\"1\":1,\"2\":0,\"4\":1}]},\"7\":{\"1\":[{\"1\":2,\"2\":0,\"5\":{\"1\":2,\"2\":0}},{\"1\":0,\"2\":0,\"3\":3},{\"1\":1,\"2\":0,\"4\":1}]},\"8\":{\"1\":[{\"1\":2,\"2\":0,\"5\":{\"1\":2,\"2\":0}},{\"1\":0,\"2\":0,\"3\":3},{\"1\":1,\"2\":0,\"4\":1}]},\"9\":0,\"10\":0,\"11\":4,\"12\":0,\"14\":{\"1\":3,\"3\":1},\"15\":\"calibri\",\"16\":10}\"=\"\">Система предупреждает водителя о непреднамеренном выходе из полосы движения с помощью визуальных, звуковых предупреждений. Непреднамеренным выходом из полосы движения считается перестроение через линию разметки с отключенным указателем поворота        </span><!--EndFragment--></p>','<p><!--StartFragment-->Система предупреждает водителя о непреднамеренном выходе из полосы движения с помощью визуальных, звуковых предупреждений<!--EndFragment--></p>','<p>The system warns the driver about an accidental traffic lane exit using visual, sound alarms.</p>','<p>The system warns the driver about an accidental traffic lane exit using visual, sound alarms. Accidental lane exit is changing the lane via a marking line with a turn signal off</p>','[{\"title_en\": \"Traffic lane exit warning function\", \"title_ru\": \"Функция предупреждения о выходе из полосы движения\"}, {\"title_en\": \"Road sign identification function\", \"title_ru\": \"Функция распознавания дорожных знаков\"}]','[]','[{\"title_en\": \"Power supply voltage\", \"title_ru\": \"Напряжение питания\", \"value_en\": \"12/24V\", \"value_ru\": \"12/24В\"}, {\"title_en\": \"Interface\", \"title_ru\": \"Интерфейс\", \"value_en\": \"CAN 2.0\", \"value_ru\": \"CAN 2.0\"}, {\"title_en\": \"Type of identified marking\", \"title_ru\": \"Типы распознаваемой разметки\", \"value_en\": \"solid, interrupted\", \"value_ru\": \"сплошная, прерывистая\"}, {\"title_en\": \"Types of identified road signs\", \"title_ru\": \"Типы распознаваемых дорожных знаков\", \"value_en\": \"Speed limiting signs\", \"value_ru\": \"знаки ограничения скорости\"}, {\"title_en\": \"