 null, \"title_ru\": \"Дисплей\", \"value_en\": null, \"value_ru\": \"12 дюймовый дисплей повышенной яркости\"}, {\"title_en\": null, \"title_ru\": \"Разрешение видеопотока\", \"value_en\": null, \"value_ru\": \"720р\"}, {\"title_en\": null, \"title_ru\": \"Интерфейс подключения камер\", \"value_en\": null, \"value_ru\": \"FPD-LINK III\"}, {\"title_en\": null, \"title_ru\": \"Камеры\", \"value_en\": null, \"value_ru\": \"две внешние камеры, позволяющие контролировать расширенную зону обзора\"}, {\"title_en\": null, \"title_ru\": \"Потребляемая мощность\", \"value_en\": null, \"value_ru\": \"не более 50 Вт\"}, {\"title_en\": null, \"title_ru\": \"Температурный диапазон\", \"value_en\": null, \"value_ru\": \"-40…+85 С\"}]',1,'2023-08-24 07:04:47','2024-06-24 09:40:33',NULL),(193,13,0,'Тензоусилитель ТУ-01 ИЮТЛ.426449.002 ТУ (С/х т-ка)','Тензоусилитель ТУ-01','(С/х т-ка)','<p><!--StartFragment--><span data-sheets-value=\"{\" 1\":2,\"2\":\"Тензоусилитель=\"\" ТУ-01=\"\" предназначен=\"\" для=\"\" работы=\"\" в=\"\" составе=\"\" систем=\"\" контроля=\"\" и=\"\" управления=\"\" сельскохозяйственной,=\"\" дорожно-строительной,=\"\" автокрановой,=\"\" специальной=\"\" другой=\"\" техники.\\nТУ-01=\"\" выполнения=\"\" следующих=\"\" функций:\\n-=\"\" преобразования=\"\" сигнала=\"\" тензодатчика=\"\" частотный=\"\" сигнал,=\"\" пропорциональный=\"\" измеренному=\"\" сигналу;\\n-=\"\" формирования=\"\" команд=\"\" can-шину=\"\" индикации=\"\" измеренного=\"\" на=\"\" экране=\"\" монитора.\"}\"=\"\" data-sheets-userformat=\"{\" 2\":342527,\"3\":{\"1\":0,\"3\":1},\"4\":{\"1\":2,\"2\":16776960},\"5\":{\"1\":[{\"1\":2,\"2\":0,\"5\":{\"1\":2,\"2\":0}},{\"1\":0,\"2\":0,\"3\":3},{\"1\":1,\"2\":0,\"4\":1}]},\"6\":{\"1\":[{\"1\":2,\"2\":0,\"5\":{\"1\":2,\"2\":0}},{\"1\":0,\"2\":0,\"3\":3},{\"1\":1,\"2\":0,\"4\":1}]},\"7\":{\"1\":[{\"1\":2,\"2\":0,\"5\":{\"1\":2,\"2\":0}},{\"1\":0,\"2\":0,\"3\":3},{\"1\":1,\"2\":0,\"4\":1}]},\"8\":{\"1\":[{\"1\":2,\"2\":0,\"5\":{\"1\":2,\"2\":0}},{\"1\